import {getLanguage} from './i18n.js';

const c=(zh,en)=>getLanguage()==='en'?en:zh;
const repo='https://github.com/ChefDavid0815/roseraie-agent';
const release=`${repo}/releases/tag/v0.1.0`;
const home='./assets/projects/roseraie/home.png';
const approval='./assets/projects/roseraie/file-approval.png';
const mark='./assets/projects/roseraie/mark.svg';

const flourish=`<svg class="rose-flourish" viewBox="0 0 600 125" fill="none" aria-hidden="true"><path d="M8 84c65-69 75 55 139-15 39-43 67-23 100 5 21 18 37 2 53-18 16 20 32 36 53 18 33-28 61-48 100-5 64 70 74-54 139 15"/><path d="M82 89c-18-7-24-23-14-38 12 3 19 17 14 38Zm50-27c-2-22 6-35 21-38 6 16-1 29-21 38Zm50 17c16-12 31-13 45-3-11 14-26 15-45 3Zm336 10c18-7 24-23 14-38-12 3-19 17-14 38Zm-50-27c2-22-6-35-21-38-6 16 1 29 21 38Zm-50 17c-16-12-31-13-45-3 11 14 26 15 45 3Z"/><path d="M300 5c14 17 21 28 21 40 0 12-8 20-21 28-13-8-21-16-21-28 0-12 7-23 21-40Zm-16 61-13 32h58l-13-32M300 73v42"/><circle cx="300" cy="46" r="5"/><circle cx="249" cy="74" r="3"/><circle cx="351" cy="74" r="3"/></svg>`;
const petals=(count=14)=>`<div class="rose-petals" aria-hidden="true">${Array.from({length:count},(_,i)=>`<i style="--drift:${(i-7)*13}px;--left:${(i*31+13)%96}%;--delay:-${(i*1.19).toFixed(2)}s;--duration:${11+i%5*2}s"></i>`).join('')}</div>`;
const actions=()=>`<div class="rose-actions"><a class="rose-action-main" href="${release}" target="_blank" rel="noopener noreferrer">${c('下载 Windows 版','Download for Windows')} <span>↓</span></a><a href="${repo}" target="_blank" rel="noopener noreferrer">GitHub <span>↗</span></a><a href="./post.html?article=roseraie">${c('读蔷薇工坊手记','Read the atelier notes')} <span>↗</span></a></div>`;

const scenes={
  salon:{zh:'灵感沙龙',en:'THE SALON',caption:['真实 Windows 桌面界面，展示创作入口与工作台。','Actual Windows interface showing the creative home and workbench.'],render:()=>`<figure class="rose-scene rose-scene--capture"><img src="${home}" width="2304" height="1517" alt="${c('Roseraie 桌面应用的实际首页','Actual Roseraie desktop home')}" loading="lazy"><figcaption>01 / ${c('真实软件画面','ACTUAL APPLICATION')}</figcaption></figure>`},
  weave:{zh:'织思手账',en:'THE WEAVE',caption:['构思、质询、定稿：三个视角围绕一个目标。','Frame, question, craft: three passes around a goal.'],render:()=>`<div class="rose-scene rose-scene--weave"><div class="rose-weave-orbit"><span>I</span><span>II</span><span>III</span><b>R</b></div><div class="rose-weave-copy"><span>LE CARNET DES IDÉES</span><strong>${c('让念头<br>有迹可循。','LET AN IDEA<br>FIND ITS WAY.')}</strong><p>${c('构思 / 质询 / 定稿','FRAME / QUESTION / CRAFT')}</p></div><div class="rose-weave-stem" aria-hidden="true"></div></div>`},
  approval:{zh:'改动确认',en:'REVIEW FIRST',caption:['真实测试中的文件改动确认；写入之前先由人审阅。','Actual file-change approval from a controlled test; a person reviews before writing.'],render:()=>`<figure class="rose-scene rose-scene--capture rose-scene--approval"><img src="${approval}" width="2304" height="1517" alt="${c('Roseraie 文件改动确认的实际测试截图','Actual Roseraie file-change approval test')}" loading="lazy"><figcaption>03 / ${c('真实测试截图','ACTUAL TEST CAPTURE')}</figcaption></figure>`}
};

export function roseraieGallery(id='salon'){
  const active=scenes[id]||scenes.salon;
  return `<section class="rose-gallery" data-rose-gallery="${id}"><div class="rose-gallery-heading"><span>THE ATELIER / PLATES I–III</span><p>${c('翻阅一座有能力也有分寸的工坊。','Turn the pages of an atelier with both ability and restraint.')}</p></div><div class="rose-gallery-layout"><div class="rose-gallery-rail" role="group" aria-label="${c('切换展柜画面','Choose an exhibit plate')}">${Object.entries(scenes).map(([key,scene],i)=>`<button type="button" data-rose-view="${key}" aria-pressed="${key===id}"><small>0${i+1}</small><span>${c(scene.zh,scene.en)}</span><b>↗</b></button>`).join('')}<p>${c('画面与测试截图均标明来源。','Artwork and actual test captures are labelled.')}</p></div><div class="rose-gallery-stage" aria-live="polite">${active.render()}</div></div><div class="rose-gallery-caption"><span>FIG. 0${Object.keys(scenes).indexOf(id)+1}</span><span>${c(...active.caption)}</span><span>RO S E R A I E  /  2026</span></div></section>`;
}
export function changeRoseraieView(button){
  const host=button.closest('[data-rose-gallery]');const id=button.dataset.roseView;
  if(!host||!scenes[id]||host.dataset.roseGallery===id)return;
  host.dataset.roseGallery=id;
  host.querySelectorAll('[data-rose-view]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));
  host.querySelector('.rose-gallery-stage').innerHTML=scenes[id].render();
  host.querySelector('.rose-gallery-caption').innerHTML=`<span>FIG. 0${Object.keys(scenes).indexOf(id)+1}</span><span>${c(...scenes[id].caption)}</span><span>RO S E R A I E  /  2026</span>`;
  document.dispatchEvent(new Event('roseraie:render'));
}

export function roseraieCard(){
  return `<article class="exhibit exhibit--roseraie" id="project-roseraie"><div class="rose-ribbon"><span>CHEFZC / THE DIGITAL COLLECTION</span><span>NO. 08 <b>✧</b> RO S E R A I E · 0.1.0</span></div><div class="rose-hero">${petals()}<div class="rose-hero-copy"><span class="rose-overline">LE SALON DES POSSIBLES / 2026</span>${flourish}<h3>Roseraie<span>.</span></h3><p class="rose-hero-cn">蔷薇工坊</p><h4>${c('让灵感，在此盛放。','A little grace in every great idea.')}</h4><p>${c('从一句轻轻写下的念头，到一件真正完成的作品。为本地工作而生的通用 Agent，把构思、执行和审阅安放在同一间工坊。','From a small idea to a finished piece. A local-first general agent brings thinking, action and review into one carefully composed atelier.')}</p><button type="button" data-project="roseraie">${c('推开工坊的门','Enter the atelier')} <span>↗</span></button></div><div class="rose-hero-art"><div class="rose-aura"></div><div class="rose-cameo"><div class="rose-cameo-inner"><img src="${mark}" alt="" width="96" height="96"><strong>R</strong><small>YOUR QUIET COMPANION</small></div></div><div class="rose-preview-window"><span>RO S E R A I E / 0.1.0 <b>− □ ×</b></span><img src="${home}" width="2304" height="1517" alt="${c('Roseraie 桌面应用首页实拍','Actual Roseraie desktop home')}" loading="lazy"><small>${c('真实桌面界面 / Windows x64','ACTUAL DESKTOP INTERFACE / WINDOWS x64')}</small></div><div class="rose-art-seal">✧ <span>IDEAS<br>IN BLOOM</span></div></div><div class="rose-hero-foot"><span>01 / THE ROCOCO AGENT</span><span>LOCAL WORKSPACE · HUMAN APPROVAL · 中 / EN</span></div></div><div class="rose-prologue"><div><span>PROLOGUE / A GENTLER KIND OF AGENT</span><h3>${c('优雅地构思。<br><em>认真地执行。</em>','THINK WITH GRACE.<br><em>ACT WITH CARE.</em>')}</h3></div><p>${c('Roseraie 可以阅读工作空间、调用工具、生成计划与记忆片段。文件改动和命令执行先经过确认；每一步都留在本地记录里，方便回看。花饰之外，是清楚的边界。','Roseraie can read a workspace, call tools, shape plans and keep context. File changes and commands require approval; its local journal makes steps reviewable. Beneath the ornament is a clear boundary.')}</p></div><div class="rose-triptych"><div><span>I / IDEA</span><b>✧</b><strong>${c('构思','FRAME')}</strong><p>${c('为念头找到路径','Give an idea its first shape')}</p></div><div><span>II / INQUIRY</span><b>❦</b><strong>${c('质询','QUESTION')}</strong><p>${c('换一双眼睛再看','Look again from another angle')}</p></div><div><span>III / CRAFT</span><b>✦</b><strong>${c('定稿','CRAFT')}</strong><p>${c('打磨，验证，交付','Polish, verify and hand over')}</p></div></div>${roseraieGallery()}<div class="rose-ledger"><div><b>03</b><span>${c('织思阶段','WEAVE PASSES')}</span></div><div><b>02</b><span>${c('确认关口','APPROVAL GATES')}</span></div><div><b>01</b><span>${c('本地工坊','LOCAL ATELIER')}</span></div></div><div class="rose-closing"><div>${flourish}<span>UNE IDÉE PEUT TOUT CHANGER.</span><strong>${c('给下一个想法，<br>留一朵玫瑰。','LET THE NEXT IDEA<br>TAKE ROOT.')}</strong></div>${actions()}</div><footer class="rose-footer"><span>RO S E R A I E / 蔷薇工坊</span><span>CHEFZC · 2026 <b>✧</b> VERSION 0.1.0</span></footer></article>`;
}

export function roseraieDetail(view='salon'){return `<div class="rose-detail"><div class="rose-detail-head">${flourish}<span>ATELIER Nº 08 / WINDOWS x64 / 0.1.0</span><h2 id="dialog-title">Roseraie<span>.</span></h2><p>${c('让灵感，在此盛放。','A little grace in every great idea.')}</p></div>${roseraieGallery(view)}<div class="rose-detail-grid"><section><small>I / THE WORKBENCH</small><h3>${c('能做事，也知道何时停下来。','An agent that knows when to pause.')}</h3><p>${c('在本地工作空间里对话、读取文件、调用工具；文件写入和命令执行之前弹出确认。可用检查点和记录回望过程，三段式织思让构思、质询与定稿更有条理。','Chat inside a local workspace, read files and call tools. Approval gates precede writes and commands. Checkpoints and a journal make work traceable; the three-pass Weave gives ideas a path from frame to critique to craft.')}</p></section><section><small>II / THE HONEST EDITION</small><h3>${c('第一版，花已经开了。','An early edition in bloom.')}</h3><p>${c('v0.1.0 已通过 12 项测试、生产构建及 Windows 桌面基本检查，并在真实 Codex CLI 流程里完成受控修复。Claude 服务端测试返回 403，Gemini 未安装；其他 API 预设和跨环境表现仍待验证。Windows 安装包与便携包未签名。','v0.1.0 passed 12 tests, a production build and basic Windows desktop checks, plus a controlled repair through a real Codex CLI flow. Claude returned a provider-side 403, Gemini was not installed, and other API presets and cross-environment behavior remain unverified. Windows packages are unsigned.')}</p></section></div>${actions()}</div>`;}

export function roseraiePostArt(){return `<div class="post-art post-art--roseraie" aria-hidden="true">${petals(9)}<div class="rose-post-top"><span>THE ATELIER JOURNAL / NOTE XI</span><span>MMXXVI · AUTUMN</span></div>${flourish}<div class="rose-post-title"><small>UNE IDÉE PEUT TOUT CHANGER</small><strong>Roseraie<i>.</i></strong><span>蔷 薇 工 坊</span></div><div class="rose-post-cameo"><img src="${mark}" alt=""><b>R</b></div><div class="rose-post-bottom"><span>A LITTLE GRACE IN EVERY GREAT IDEA</span><span>CHEFZC / 2026</span></div></div>`;}

export function roseraieNowArt(){return `<div class="milestone-art rose-now-art" aria-hidden="true">${petals(8)}<div class="rose-now-head"><span>RO S E R A I E</span><b>✧</b></div><div class="rose-now-cameo"><img src="${mark}" alt=""><strong>R</strong></div><span class="rose-now-name">Roseraie<i>.</i></span><div class="rose-now-steps"><span>I <b>FRAME</b></span><span>II <b>QUESTION</b></span><span>III <b>CRAFT</b></span></div><div class="rose-now-foot"><span>THE QUIET AGENT<br>23 SEP 2026</span><b>0.1.0 ↗</b></div></div>`;}
